const raw = $('Roster JSON Form').first().json.snapshot_json;
if (typeof raw !== 'string' || raw.length > 500000) throw new Error('snapshot_json must be JSON text under 500 KB');
let s; try { s=JSON.parse(raw); } catch { throw new Error('Invalid JSON'); }
const fail=m=>{throw new Error(m)};
const obj=x=>x && typeof x==='object' && !Array.isArray(x);
if(!obj(s)) fail('Snapshot must be an object');
if(s.schema_version!==1 || s.platform!=='yahoo') fail('schema_version must be 1 and platform yahoo');
if(typeof s.league_id!=='string'||!s.league_id.trim()) fail('league_id required');
if(!Number.isInteger(s.season)||s.season<2000||s.season>2100) fail('season required');
if(!Number.isInteger(s.current_week)||s.current_week<1||s.current_week>18) fail('current_week must be 1..18');
if(typeof s.is_sample!=='boolean') fail('is_sample boolean required');
if(typeof s.captured_at!=='string'||!/^\d{4}-\d{2}-\d{2}T/.test(s.captured_at)||!Number.isFinite(Date.parse(s.captured_at))) fail('captured_at ISO timestamp required');
if(!obj(s.league_settings)||typeof s.league_settings.verified!=='boolean'||typeof s.league_settings.ppr!=='number'||s.league_settings.ppr<0||s.league_settings.ppr>2) fail('league_settings needs ppr and verified');
const positions=['QB','RB','WR','TE','K','DEF','DL','LB','DB','DT','DE','CB','S'];
const slots=[...positions,'FLEX','SUPER_FLEX','BN','IR','IR+'];
const teams='ARI ATL BAL BUF CAR CHI CIN CLE DAL DEN DET GB HOU IND JAX KC LAC LAR LV MIA MIN NE NO NYG NYJ PHI PIT SEA SF TB TEN WAS FA'.split(' ');
if(!obj(s.league_settings.roster_slots)||!Object.keys(s.league_settings.roster_slots).length) fail('roster_slots required');
for(const [k,v] of Object.entries(s.league_settings.roster_slots)) if(!slots.includes(k)||!Number.isInteger(v)||v<0||v>40) fail('Invalid roster slot '+k);
if(!Array.isArray(s.roster)||!s.roster.length||s.roster.length>100||!Array.isArray(s.waiver_players)||s.waiver_players.length>1000) fail('roster and waiver_players arrays required');
const seen=new Set();
for(const [label,players] of [['roster',s.roster],['waiver_players',s.waiver_players]]) for(const p of players){
 if(!obj(p)||typeof p.name!=='string'||p.name.trim().length<2||p.name.length>100||!/[\p{L}]/u.test(p.name)||/[<>\x00-\x1f]/.test(p.name)) fail(label+': invalid player name');
 if(!Array.isArray(p.positions)||!p.positions.length||p.positions.some(x=>!positions.includes(x))) fail(p.name+': invalid positions');
 if(!teams.includes(p.team)) fail(p.name+': invalid team abbreviation');
 if(p.opponent!==undefined&&p.opponent!==null&&p.opponent!=='BYE'&&!teams.filter(t=>t!=='FA').includes(p.opponent)) fail(p.name+': invalid opponent');
 if(label==='roster'&&!slots.includes(p.slot)) fail(p.name+': slot required');
 if(label==='roster'&&!['BN','IR','IR+','FLEX','SUPER_FLEX'].includes(p.slot)&&!p.positions.includes(p.slot)) fail(p.name+': slot incompatible with positions');
 if(label==='roster'&&p.slot==='FLEX'&&!p.positions.some(x=>['RB','WR','TE'].includes(x))) fail(p.name+': FLEX incompatible');
 if(label==='roster'&&p.slot==='SUPER_FLEX'&&!p.positions.some(x=>['QB','RB','WR','TE'].includes(x))) fail(p.name+': SUPER_FLEX incompatible');
 const key=(p.player_id||p.name.trim().toLowerCase())+'|'+p.team;
 if(seen.has(key)) fail('Duplicate player across roster/waivers: '+p.name); seen.add(key);
}
return [{json:{snapshot_json:JSON.stringify(s),league_id:s.league_id,is_sample:s.is_sample,captured_at:s.captured_at}}];
